// pyfloat.mjs
// Emulates CPython's float() parsing and repr()/str() formatting so that
// numeric behavior matches the original Python program bit-for-bit.

const DIGIT_PART = String.raw`\d(?:_?\d)*`;
const FLOAT_RE = new RegExp(
  String.raw`^\s*[+-]?(?:(?:${DIGIT_PART}(?:\.${DIGIT_PART}?)?|\.${DIGIT_PART})(?:[eE][+-]?${DIGIT_PART})?|inf(?:inity)?|nan)\s*$`,
  'i',
);

// Parse a string the way Python's float() does.
// Returns the parsed number, or null when Python would raise ValueError.
export function parsePythonFloat(text) {
  if (!FLOAT_RE.test(text)) return null;
  const cleaned = text.trim().replace(/_/g, '');
  if (/nan/i.test(cleaned)) return NaN;
  const infMatch = /^([+-]?)inf/i.exec(cleaned);
  if (infMatch) return infMatch[1] === '-' ? -Infinity : Infinity;
  return Number(cleaned);
}

// Split a finite JS number into its shortest round-trip decimal digits and
// the decimal exponent of the leading digit (adjusted exponent).
function shortestParts(x) {
  const s = String(x);
  let digits;
  let adjexp;
  const eIdx = s.indexOf('e');
  if (eIdx !== -1) {
    const mantissa = s.slice(0, eIdx);
    adjexp = parseInt(s.slice(eIdx + 1), 10);
    digits = mantissa.replace('.', '');
  } else if (s.includes('.')) {
    const dot = s.indexOf('.');
    const intPart = s.slice(0, dot);
    const fracPart = s.slice(dot + 1);
    if (intPart !== '0') {
      adjexp = intPart.length - 1;
      digits = intPart + fracPart;
    } else {
      const leadZeros = /^0*/.exec(fracPart)[0].length;
      adjexp = -(leadZeros + 1);
      digits = fracPart.slice(leadZeros);
    }
  } else {
    adjexp = s.length - 1;
    digits = s;
  }
  digits = digits.replace(/0+$/, '');
  return { digits, adjexp };
}

// Format a number exactly like Python's repr(float) (same as str(float)).
export function reprPythonFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const neg = x < 0 || Object.is(x, -0);
  if (x === 0) return neg ? '-0.0' : '0.0';

  const { digits, adjexp } = shortestParts(Math.abs(x));
  const sign = neg ? '-' : '';

  if (adjexp >= -4 && adjexp < 16) {
    // Fixed-point notation; integral values keep a trailing ".0".
    if (adjexp >= 0) {
      if (digits.length > adjexp + 1) {
        return sign + digits.slice(0, adjexp + 1) + '.' + digits.slice(adjexp + 1);
      }
      return sign + digits + '0'.repeat(adjexp + 1 - digits.length) + '.0';
    }
    return sign + '0.' + '0'.repeat(-adjexp - 1) + digits;
  }
  // Scientific notation; exponent always signed and at least two digits.
  const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
  const expSign = adjexp < 0 ? '-' : '+';
  const expDigits = String(Math.abs(adjexp)).padStart(2, '0');
  return sign + mantissa + 'e' + expSign + expDigits;
}

