// decimal.mjs
// Minimal reimplementation of Python's decimal.Decimal covering exactly what
// the original program needs: construction from a string, exact division by
// 2 under the default context (28 significant digits, ROUND_HALF_EVEN), and
// Python's str(Decimal) formatting.
//
// A finite value is stored as sign ('-' or ''), a coefficient digit string
// (no leading zeros, at least '0'), and a base-10 exponent, mirroring
// Decimal's (sign, digits, exponent) triple.

// Multiply a decimal digit string by 5 (string-based to stay exact for
// coefficients beyond 2^53).
function mul5(digits) {
  let carry = 0;
  let out = '';
  for (let i = digits.length - 1; i >= 0; i--) {
    const v = (digits.charCodeAt(i) - 48) * 5 + carry;
    out = String.fromCharCode(48 + (v % 10)) + out;
    carry = Math.floor(v / 10);
  }
  if (carry > 0) out = String.fromCharCode(48 + carry) + out;
  return out;
}

export class PyDecimal {
  constructor(sign, digits, exponent, special = null) {
    this.sign = sign;
    this.digits = digits;
    this.exponent = exponent;
    this.special = special; // null, 'nan', or 'inf'
  }

  // Mirrors Decimal(str): accepts fixed/scientific notation plus
  // 'nan'/'inf'/'infinity' (case-insensitive, optional sign).
  static fromString(text) {
    const m = /^([+-]?)(?:(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?|(inf(?:inity)?|nan))$/i.exec(text.trim());
    if (!m || (m[2] === undefined && !m[5]) || (m[2] !== undefined && m[2] === '' && (m[3] === undefined || m[3] === ''))) {
      throw new Error(`Invalid decimal literal: ${text}`);
    }
    const sign = m[1] === '-' ? '-' : '';
    if (m[5]) {
      return new PyDecimal(sign, '0', 0, m[5].toLowerCase().startsWith('nan') ? 'nan' : 'inf');
    }
    const intPart = m[2] || '';
    const fracPart = m[3] || '';
    const expPart = m[4] ? parseInt(m[4], 10) : 0;
    let digits = (intPart + fracPart).replace(/^0+/, '');
    if (digits === '') digits = '0';
    return new PyDecimal(sign, digits, expPart - fracPart.length);
  }

  // Exact halving, matching Decimal('x') / 2 in the default context.
  // Coefficients coming from float repr have at most 17 significant digits,
  // so the exact result (at most 18 digits) always fits the 28-digit
  // context precision and no rounding ever occurs.
  divBy2() {
    if (this.special) return new PyDecimal(this.sign, '0', 0, this.special);
    // Ideal exponent of a / b is exp(a) - exp(b); here exp(2) = 0.
    const idealExp = this.exponent;
    if (this.digits === '0') {
      return new PyDecimal(this.sign, '0', idealExp);
    }
    // x / 2 == (x * 5) / 10
    let digits = mul5(this.digits);
    let exp = this.exponent - 1;
    // Strip trailing zeros, but never past the ideal exponent.
    while (exp < idealExp && digits.endsWith('0')) {
      digits = digits.slice(0, -1);
      exp += 1;
    }
    return new PyDecimal(this.sign, digits, exp);
  }

  // Reproduces Python's str(Decimal).
  toString() {
    if (this.special === 'nan') return this.sign + 'NaN';
    if (this.special === 'inf') return this.sign + 'Infinity';
    const { digits, exponent } = this;
    const adjexp = exponent + digits.length - 1;
    let body;
    if (exponent <= 0 && adjexp >= -6) {
      // Fixed-point notation.
      if (exponent === 0) {
        body = digits;
      } else {
        const point = digits.length + exponent;
        body = point > 0
          ? digits.slice(0, point) + '.' + digits.slice(point)
          : '0.' + '0'.repeat(-point) + digits;
      }
    } else {
      // Scientific notation.
      const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
      body = mantissa + 'E' + (adjexp < 0 ? '-' : '+') + Math.abs(adjexp);
    }
    return this.sign + body;
  }
}

