// argparse.mjs
// Minimal reimplementation of the subset of Python's argparse used by the
// original script: two required options (--amount with type=float,
// --currency with type=str) plus -h/--help. Error messages, usage text,
// and exit codes mirror argparse (exit 2 on error, exit 0 after --help).

import { parsePythonFloat } from './pyfloat.mjs';

const LONG_OPTIONS = ['--help', '--amount', '--currency'];
// argparse's _negative_number_matcher: a token that looks like a negative
// number is treated as a value, not an option.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --amount AMOUNT --currency CURRENCY`;
}

function helpText(prog) {
  return [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help           show this help message and exit',
    '  --amount AMOUNT',
    '  --currency CURRENCY',
    '',
  ].join('\n');
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Resolve a long option name (without '='), allowing unambiguous prefix
// abbreviations exactly like argparse's allow_abbrev=True.
function resolveLong(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
  if (matches.length === 1) return matches[0];
  return null;
}

function looksLikeValue(token) {
  return token === '-' || !token.startsWith('-') || NEGATIVE_NUMBER_RE.test(token);
}

export function parseArgs(argv, prog) {
  const values = { amount: undefined, currency: undefined };
  const extras = [];

  let i = 0;
  let onlyPositional = false;
  while (i < argv.length) {
    const token = argv[i];
    if (onlyPositional) {
      extras.push(token);
      i += 1;
      continue;
    }
    if (token === '--') {
      onlyPositional = true;
      i += 1;
      continue;
    }
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? undefined : token.slice(eq + 1);
      const resolved = resolveLong(name);
      if (resolved === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (resolved === '--help') {
        process.stdout.write(helpText(prog));
        process.exit(0);
      }
      const dest = resolved.slice(2);
      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length && looksLikeValue(argv[i + 1])) {
        value = argv[i + 1];
        i += 2;
      } else {
        fail(prog, `argument ${resolved}: expected one argument`);
      }
      if (dest === 'amount') {
        const parsed = parsePythonFloat(value);
        if (parsed === null) {
          fail(prog, `argument --amount: invalid float value: '${value}'`);
        }
        values.amount = parsed;
      } else {
        values.currency = value;
      }
      continue;
    }
    if (token === '-h') {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }
    // Unknown short option or positional: argparse collects these and
    // reports them together at the end.
    extras.push(token);
    i += 1;
  }

  const missing = [];
  if (values.amount === undefined) missing.push('--amount');
  if (values.currency === undefined) missing.push('--currency');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

